// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint128 amount) public {
        // keep the amount admissible: positive and affordable by c
        bound(amount, 1, 1e18);
        vm.deal(address(c), amount);

        // owner of c is address(this) (msg.sender at deployment); drive as owner,
        // sending the contract's own value back to the contract itself
        vm.prank(address(this));
        c.sendMoney(address(c), uint256(amount));

        // rule: the payment to address(c) triggers c's payable fallback exactly once
        assertTrue(c.depositsCount() == 1, "payment routed to _target must hit c's fallback");
    }
}
